import { useEffect, useState } from "react";
import { Button, Card, Stack, Text, useData } from "a2ui";

function format(ms: number) {
  const s = Math.floor(ms / 1000);
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}.${Math.floor((ms % 1000) / 100)}`;
}

export default function App() {
  const [, setLaps] = useData<{ time: string }[]>("/timer/laps", []);
  const [startedAt, setStartedAt] = useState<number | null>(null);
  const [elapsed, setElapsed] = useState(0);

  useEffect(() => {
    if (startedAt === null) return;
    const id = setInterval(() => setElapsed(Date.now() - startedAt), 100);
    return () => clearInterval(id);
  }, [startedAt]);

  return (
    <Card>
      <Stack gap={3} align="center">
        <Text variant="h1" style={{ fontVariantNumeric: "tabular-nums" }}>{format(elapsed)}</Text>
        <Stack direction="horizontal" gap={2}>
          <Button variant="primary" onClick={() => setStartedAt(startedAt === null ? Date.now() - elapsed : null)}>
            {startedAt === null ? "Start" : "Stop"}
          </Button>
          <Button disabled={startedAt === null} onClick={() => setLaps((previous) => [...previous, { time: format(elapsed) }])}>
            Lap
          </Button>
        </Stack>
      </Stack>
    </Card>
  );
}
